; An end-to-end timing and ROM test for layer 4 (M5 step 5.9: the ROM in
; DDR behind Gg.RomPort). A line interrupt on every line rewrites colour 0
; (the whole picture is tile 0, all colour 0), so where each line changes
; colour depends on the CPU's exact timing; the main loop meanwhile reads
; pseudo-random data from banks 1-3 at a stride (DDR misses), and the
; colour mixes its running sum with R. Every frame is the same: the work
; fits in the vertical blank (no line interrupt can split it), then the
; loop waits in HALT, where interrupts are taken on HALT's 4 T-state grid;
; each frame moves that grid's phase by a constant, which PAD makes 0 mod
; 4, so every frame repeats the last (59736 T-states a frame). The spec's frame
; is the golden (systems/gg/test/golden/vga/raster.png); a ROM byte or a
; T-state wrong on the board shows in it.

.INCLUDE "gg.inc"

.DEFINE STEPS 100
.DEFINE PAD 2             ; ld a, 0 x PAD after the work: tunes the frame to one HALT phase
.DEFINE FRAMEFLAG $C030

.BANK 0 SLOT 0
.SECTION "main" FREE
main:
  VDPREG 0, $04
  VDPREG 1, $00
  VDPREG 2, $FF
  VDPREG 5, $7F
  VDPREG 6, $FB
  VDPREG 7, $00
  VDPREG 10, $00
  ; tile 0 all colour 0, the name table all tile 0, no sprites
  xor a
  out ($BF), a
  ld a, $40
  out ($BF), a
  ld bc, 32
-:
  xor a
  out ($BE), a
  dec bc
  ld a, b
  or c
  jr nz, -
  xor a
  out ($BF), a
  ld a, $78
  out ($BF), a
  ld bc, 32 * 28 * 2
-:
  xor a
  out ($BE), a
  dec bc
  ld a, b
  or c
  jr nz, -
  xor a
  out ($BF), a
  ld a, $7F
  out ($BF), a
  ld a, $D0
  out ($BE), a
  SETIRQ irq
  VDPREG 0, $14           ; line interrupts
  VDPREG 1, $60           ; display on, frame interrupts
  ei
frame:
  halt                    ; until the frame interrupt (the handler returns here)
  ld a, (FRAMEFLAG)
  or a
  jr z, frame
  xor a
  ld (FRAMEFLAG), a
  ld r, a                 ; R from 0 each frame
  ld e, a                 ; the running sum
  ld hl, $8000
  ld bc, STEPS
loop:
  ; slot 2's bank: 1, 2, 3 by the step count
  ld a, b
  and 3
  jr nz, +
  inc a
+:
  ld ($FFFF), a
  ld a, e
  add a, (hl)
  ld e, a
  ld a, l
  add a, 37
  ld l, a
  jr nc, +
  inc h
  ld a, h
  cp $A0                  ; within 8000h-9FFFh (the data)
  jr c, +
  ld h, $80
+:
  dec bc
  ld a, b
  or c
  jr nz, loop
.REPT PAD
  ld a, 0
.ENDR
  jr frame

; Both interrupts: the frame one sets FRAMEFLAG; a line one writes colour 0.
irq:
  push af
  in a, ($BF)
  bit 7, a
  jr z, +
  ld a, 1
  ld (FRAMEFLAG), a
  pop af
  ei
  ret
+:
  xor a
  out ($BF), a
  ld a, $C0
  out ($BF), a
  ld a, r
  xor e
  out ($BE), a
  rrca
  rrca
  rrca
  out ($BE), a
  pop af
  ei
  ret
.ENDS

.BANK 1 SLOT 1
.ORGA $4000
